def transform(g):
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]
    for r0 in range(h):
        for r1 in range(r0 + 1, h + 1):
            # For this band, a column is eligible only if it has one repeated color.
            vals = []
            for c in range(w):
                v = g[r0][c]
                vals.append(v if all(g[r][c] == v for r in range(r0, r1)) else None)
            c = 0
            while c < w:
                v = vals[c]
                if v is None:
                    c += 1
                    continue
                c0 = c
                while c < w and vals[c] == v:
                    c += 1
                c1 = c
                height, width = r1-r0, c1-c0
                if height < 4 or width < 5 or height*width < 20:
                    continue
                # Retain only rectangles that cannot expand vertically.
                if r0 > 0 and all(g[r0-1][x] == v for x in range(c0,c1)):
                    continue
                if r1 < h and all(g[r1][x] == v for x in range(c0,c1)):
                    continue
                for rr in range(r0,r1):
                    for cc in range(c0,c1):
                        out[rr][cc] = 4
    return out

